constexpr int GetValCT(int x) {
  return (x > 10) ? x * 2 : x;
}

// Compile-Time usage: Result evaluated at compile time
constexpr int CT_SIZE = GetValCT(12);

// Constant expression used for memory layout/size
int ct_buffer[CT_SIZE]; // Array size is 24

// Runtime evaluation (forced runtime dispatch)
int GetValRT(int x) { return x * 2; }
int rt_size = GetValRT(5);

// int rt_buffer[rt_size]; // Error: Not a constant expression
std::vector<int> rt_vec(rt_size); // Runtime allocation
